// backend/services/matWhRequestKeys.js
// Idempotency for postings a phone may resend (see MatWhRequestKey.js).
// Callers check findRequestKey before any validation -- a replay of a
// request that completed the document must still answer "done", not fail
// on the now-changed status -- then claimRequestKey inside the posting's
// own transaction, after its document lock, so two identical requests at
// once serialize on that lock and the second finds the key.
import { MatWhRequestKey } from '../models/MatWhRequestKey.js';

// Keys are generated by the client; anything else is ignored rather than
// rejected, so a client that doesn't send one behaves exactly as before.
export function normalizeRequestKey(key) {
    const k = typeof key === 'string' ? key.trim() : '';
    return k && k.length <= 64 ? k : null;
}

export async function findRequestKey(requestKey, transaction) {
    if (!requestKey) return null;
    return MatWhRequestKey.findOne({ where: { requestKey }, transaction });
}

// true = this request owns the key (go ahead and post); false = already
// applied (skip the posting).
export async function claimRequestKey(requestKey, { action, refId, userId }, transaction) {
    if (!requestKey) return true;
    if (await findRequestKey(requestKey, transaction)) return false;
    try {
        await MatWhRequestKey.create({ requestKey, action, refId: refId ?? null, userId: userId ?? null }, { transaction });
        return true;
    } catch (err) {
        if (err.name === 'SequelizeUniqueConstraintError') return false;
        throw err;
    }
}

// For creates with no document row to lock first (a new item, an extra
// stock-count line): the key is claimed up front -- its unique index makes
// two identical requests take turns -- then create() runs and the key
// records what it made. If create() fails the key is released, so a retry
// still runs it. Returns { result } when this request did the work, or
// { replay: true, refId } when an earlier one did (refId is null while
// that earlier one is still running).
export async function runOnceWithKey(requestKey, { action, userId }, create) {
    if (!requestKey) return { result: await create() };
    const existing = await findRequestKey(requestKey);
    if (existing) return { replay: true, refId: existing.refId };
    let keyRow;
    try {
        keyRow = await MatWhRequestKey.create({ requestKey, action, userId: userId ?? null });
    } catch (err) {
        if (err.name !== 'SequelizeUniqueConstraintError') throw err;
        const other = await findRequestKey(requestKey);
        return { replay: true, refId: other?.refId ?? null };
    }
    try {
        const result = await create();
        await keyRow.update({ refId: result?.id ?? null });
        return { result };
    } catch (err) {
        await keyRow.destroy().catch(() => {});
        throw err;
    }
}
